def complete_lines(grid, marker=5, fill=2):
    """Fill gaps in the marker's straight line segments: line rows span their extreme markers; vertical lines are the span's end columns plus columns with markers off those rows."""
    H,W=len(grid),len(grid[0])
    M={(i,j) for i in range(H) for j in range(W) if grid[i][j]==marker}
    if not M: return [r[:] for r in grid]
    line_rows={r for r in range(H) if sum(1 for i,j in M if i==r)>=2}
    segs=[]
