import math
def complete_lines(grid, marker=5, fill=2):
    """Complete the marker's line drawing: fill gaps in major horizontal lines (rows with at least half the max marker count) and in vertical lines (the span's end columns plus columns with markers off those rows)."""
    H,W=len(grid),len(grid[0])
    M={(i,j) for i in range(H) for j in range(W) if grid[i][j]==marker}
    if not M: return [r[:] for r in grid]
    cnt={r:sum(1 for i,j in M if i==r) for r in range(H)}
    mx=max(cnt.values())
    line_rows=sorted(r for r in cnt if cnt[r]>=max(2,math.ceil(mx/2)))
    segs=[]
    if len(line_rows)>=2:
        cols=[j for i,j in M if i in line_rows]
        c0,c1=min(cols),max(cols)
        for r in line_rows: segs.append(('h',r,c0,c1))
        vcols={c0,c1}|{j for i,j in M if i not in line_rows}
    else:
        vcols={j for j in range(W) if sum(1 for i,k in M if k==j)>=2}
    for c in vcols:
        rs=[i for i,j in M if j==c]
        if len(rs)>=2: segs.append(('v',c,min(rs),max(rs)))
    out=[r[:] for r in grid]
    for s in segs:
        if s[0]=='h':
            _,r,a,b=s
            for j in range(a,b+1):
                if out[r][j]!=marker: out[r][j]=fill
        else:
            _,c,a,b=s
            for i in range(a,b+1):
                if out[i][c]!=marker: out[i][c]=fill
    return out

