def complete_lines(grid, marker=5, fill=2):
    """Complete the marker's line drawing: fill the bounding box's top/bottom rows and side columns, plus inner lines (columns/rows with >=2 markers strictly inside), keeping markers."""
    H,W=len(grid),len(grid[0])
    M={(i,j) for i in range(H) for j in range(W) if grid[i][j]==marker}
    if not M: return [r[:] for r in grid]
    r0=min(i for i,_ in M); r1=max(i for i,_ in M)
    c0=min(j for _,j in M); c1=max(j for _,j in M)
    out=[r[:] for r in grid]
    for j in range(c0,c1+1):
        for i in (r0,r1):
            if out[i][j]!=marker: out[i][j]=fill
    for i in range(r0,r1+1):
        for j in (c0,c1):
            if out[i][j]!=marker: out[i][j]=fill
    for c in range(c0+1,c1):
        col=[i for i,j in M if j==c and r0<i<r1]
        if len(col)>=2:
            for i in range(r0,r1+1):
                if out[i][c]!=marker: out[i][c]=fill
    for r in range(r0+1,r1):
        row=[j for i,j in M if i==r and c0<j<c1]
        if len(row)>=2:
            for j in range(c0,c1+1):
                if out[r][j]!=marker: out[r][j]=fill
    return out

